.layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:22px;align-items:start}.news-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.news-card{background:#fff;border:1px solid #e8edf5;border-radius:15px;overflow:hidden;display:flex;flex-direction:column;min-width:0;box-shadow:0 8px 26px #102b5508;transition:transform .22s,box-shadow .22s}.news-card:hover{transform:translateY(-4px);box-shadow:0 16px 34px #102b5515}.cover-wrap{height:180px;position:relative;background:#e7edf6;overflow:hidden}.cover{width:100%;height:100%;display:block;object-fit:cover;transition:transform .4s}.news-card:hover .cover{transform:scale(1.04)}.cover-placeholder{width:100%;height:100%;display:grid;place-items:center;background:linear-gradient(135deg,#dbe8f8,#f4f7fb);color:#7693b7;font-size:44px}.category-pill{position:absolute;left:14px;top:14px;border-radius:22px;background:#0b4b9b;color:#fff;font-size:10px;font-weight:850;letter-spacing:.4px;padding:7px 12px;text-transform:uppercase;box-shadow:0 3px 10px #0b23452c}.category-pill.kegiatan{background:#3f8b24}.category-pill.pengumuman{background:#f0a000}.category-pill.prestasi{background:#7452c7}.news-body{padding:17px 17px 18px;display:flex;flex-direction:column;flex:1}.meta{display:flex;flex-wrap:wrap;gap:10px;color:#7a8aa1;font-size:11px;margin-bottom:12px}.meta span{display:inline-flex;align-items:center;gap:5px}.news-body h2{font-size:18px;line-height:1.35;letter-spacing:-.25px;margin:0 0 10px;font-weight:800;color:#102b55}.news-body p{font-size:13px;line-height:1.7;color:#6a7d98;margin:0 0 16px}.read{margin-top:auto;display:flex;align-items:center;justify-content:space-between;color:#064a9c;font-size:13px;font-weight:800;padding-top:8px}.arrow{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#edf4ff;font-size:19px;transition:.2s}.news-card:hover .arrow{background:var(--blue);color:white}.sidebar{display:grid;gap:18px}.side-box{background:#fff;border:1px solid #e8ed